#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static unsigned ack(unsigned m, unsigned n) {
    if (m == 0)
        return n + 1;
    if (n == 0)
        return ack(m - 1, 1);
    return ack(m - 1, ack(m, n - 1));
}
int main(void) {
    unsigned m, n;
    if (scanf("%u%u", &m, &n) != 2 || m > 3 || n > 6)
        return EXIT_FAILURE;
    printf("%u\n", ack(m, n));
