#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void) {
    FILE *in = fopen("input.txt", "rb");
    if (!in)
        return EXIT_FAILURE;
    FILE *out = fopen("copy.txt", "wb");
    if (!out) {
        fclose(in);
        return EXIT_FAILURE;
    }
    int c;
    int failed = 0;
    while ((c = fgetc(in)) != EOF)
        if (fputc(c, out) == EOF) {
            failed = 1;
            break;
        }
    if (ferror(in))
        failed = 1;
    if (fclose(in) != 0)
        failed = 1;
    if (fclose(out) != 0)
        failed = 1;
    if (failed)
        return EXIT_FAILURE;
    in = fopen("copy.txt", "rb");
    if (!in)
        return EXIT_FAILURE;
    while ((c = fgetc(in)) != EOF)
        putchar(c);
    failed = ferror(in);
    if (fclose(in) != 0)
        failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

