        return EXIT_FAILURE;
    unsigned long chars = 0, digits = 0, special = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        chars++;
        if (isdigit((unsigned char)c))
            digits++;
        else if (!isalnum((unsigned char)c) && !isspace((unsigned char)c))
            special++;
    }
    int failed = ferror(f);
    if (fclose(f) != 0)
        failed = 1;
    if (failed)
        return EXIT_FAILURE;
    printf("characters=%lu digits=%lu special=%lu\n", chars, digits, special);
}

