        return EXIT_FAILURE;
    if (fputs("1 2 3 4\n", f) == EOF) {
        fclose(f);
        return EXIT_FAILURE;
    }
    if (fclose(f) != 0)
        return EXIT_FAILURE;
    f = fopen("numbers.txt", "r");
    if (!f)
        return EXIT_FAILURE;
    FILE *e = fopen("even.txt", "w"), *o = fopen("odd.txt", "w");
    if (!e || !o) {
        if (e)
            fclose(e);
        if (o)
            fclose(o);
        fclose(f);
        return EXIT_FAILURE;
    }
    int n, rc, failed = 0;
    while ((rc = fscanf(f, "%d", &n)) == 1)
        if (fprintf(n % 2 == 0 ? e : o, "%d\n", n) < 0) {
            failed = 1;
            break;
        }
    if (rc != EOF || ferror(f))
        failed = 1;
    if (fclose(f) != 0)
        failed = 1;
    if (fclose(e) != 0)
        failed = 1;
    if (fclose(o) != 0)
        failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

